-- HGN v0.53.0: tourist-season guide expansion and reporting support
-- Run once after v273.

on conflict(slug) do update set
 name=excluded.name,category=excluded.category,community=excluded.community,latitude=excluded.latitude,longitude=excluded.longitude,description=excluded.description,phone=coalesce(excluded.phone,hgn_guide_places.phone),website=coalesce(excluded.website,hgn_guide_places.website),amenities=excluded.amenities,caution=excluded.caution,featured=excluded.featured,source_name=excluded.source_name,source_url=excluded.source_url,verified_at=excluded.verified_at,next_review_at=excluded.next_review_at,updated_at=now();

on conflict(url) do nothing;
